import{_ as i,c as t,o as n,ai as a}from"./chunks/framework.BrjRfu4a.js";const h=JSON.parse('{"title":"Overview of Financial Products | Basics of Financial Engineering | Financial Engineering","description":"This page will explore the characteristics of major financial products, such as stocks, bonds, and derivatives, how their value is determined, and their applications in financial engineering.","frontmatter":{"title":"Overview of Financial Products | Basics of Financial Engineering | Financial Engineering","description":"This page will explore the characteristics of major financial products, such as stocks, bonds, and derivatives, how their value is determined, and their applications in financial engineering.","head":[["meta",{"property":"og:title","content":"Overview of Financial Products | Basics of Financial Engineering | Financial Engineering"}],["meta",{"property":"og:description","content":"This page will explore the characteristics of major financial products, such as stocks, bonds, and derivatives, how their value is determined, and their applications in financial engineering."}],["meta",{"property":"og:image","content":"/images/Financial-Engineering.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/financial-engineering/basics/products"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/products"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/financial-engineering/basics/products"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/products"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/financial-engineering/basics/products"}]],"date":"2025-02-07T00:00:00.000Z"},"headers":[],"relativePath":"financial-engineering/basics/products.md","filePath":"en/financial-engineering/basics/products.md"}'),s={name:"financial-engineering/basics/products.md"};function r(o,e,l,c,d,u){return n(),t("div",null,e[0]||(e[0]=[a('<h1 id="overview-of-financial-products" tabindex="-1">Overview of Financial Products <a class="header-anchor" href="#overview-of-financial-products" aria-label="Permalink to &quot;Overview of Financial Products&quot;">​</a></h1><p><strong>Basics of Financial Engineering | 2025.02.07</strong></p><p><strong>Financial products refer to various types of contracts and securities traded in the capital markets. These products are essential tools for performing key functions in financial markets, such as efficient capital allocation, risk management, and providing investment opportunities.</strong></p><p><strong>Financial engineering is the discipline that applies scientific methodologies to the design, pricing, and risk analysis of these financial products. A systematic understanding of financial products is a fundamental basis for studying financial engineering.</strong></p><p><strong>This page will explore the types and characteristics of major financial products, their valuation methods, risk factors, and how they are utilized in financial engineering.</strong></p><h2 id="_1️⃣-classification-and-functions-of-financial-products" tabindex="-1">1️⃣ Classification and Functions of Financial Products <a class="header-anchor" href="#_1️⃣-classification-and-functions-of-financial-products" aria-label="Permalink to &quot;1️⃣ Classification and Functions of Financial Products&quot;">​</a></h2><p>Financial products can be classified in various ways according to different criteria. Here, we will examine important classification methods from a financial engineering perspective and the core functions of each product group.</p><h3 id="classification-by-underlying-asset" tabindex="-1">Classification by Underlying Asset <a class="header-anchor" href="#classification-by-underlying-asset" aria-label="Permalink to &quot;Classification by Underlying Asset&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Classification of Financial Products by Underlying Assets</p><ul><li><p><strong>Physical Asset-Based Products</strong><br> Financial products based on physical assets such as land, buildings, and raw materials. Real Estate Investment Trusts (REITs) and commodity ETFs fall under this category.</p></li><li><p><strong>Financial Asset-Based Products</strong><br> Products based on financial assets such as stocks and bonds. Most financial products belong to this category.</p></li><li><p><strong>Index-Based Products</strong><br> Products linked to specific indicators such as stock indices, interest rates, and exchange rates. Index funds and stock index futures are representative examples.</p></li><li><p><strong>Credit-Based Products</strong><br> Products based on the creditworthiness of the borrower, including corporate bonds, mortgage-backed securities (MBS), and credit default swaps (CDS).</p></li></ul></div><h3 id="classification-by-cash-flow-characteristics" tabindex="-1">Classification by Cash Flow Characteristics <a class="header-anchor" href="#classification-by-cash-flow-characteristics" aria-label="Permalink to &quot;Classification by Cash Flow Characteristics&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Classification of Financial Products by Cash Flow Characteristics</p><ul><li><p><strong>Fixed Income Products</strong><br> Products that provide fixed cash flows according to a predetermined schedule. Bonds and deposits are representative examples, suitable for investors seeking relatively stable returns.</p></li><li><p><strong>Variable Income Products</strong><br> Products where returns fluctuate based on market conditions or corporate performance. Stocks and real estate investments fall under this category, suitable for investors seeking relatively high returns.</p></li><li><p><strong>Contingent Income Products</strong><br> Products that generate income only when specific conditions are met. Options and insurance are representative examples, utilized for hedging against or speculating on specific scenarios.</p></li></ul></div><h3 id="classification-by-legal-nature" tabindex="-1">Classification by Legal Nature <a class="header-anchor" href="#classification-by-legal-nature" aria-label="Permalink to &quot;Classification by Legal Nature&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Classification of Financial Products by Legal Nature</p><ul><li><p><strong>Equity Securities</strong><br> Securities that represent ownership in the issuing company, with stocks being a typical example. Owners can expect dividends and capital gains based on the company&#39;s performance.</p></li><li><p><strong>Debt Securities</strong><br> Securities that represent the borrowing obligation of the issuer, including bonds and notes. Owners have the right to receive interest and principal repayment.</p></li><li><p><strong>Derivatives</strong><br> Contracts based on the value of underlying assets, including options, futures, and swaps. They allow for leveraged effects, enabling significant transactions with a small amount of capital.</p></li><li><p><strong>Investment Funds</strong><br> Products that pool funds from various investors and are managed by professional asset managers, including mutual funds, ETFs, and hedge funds. They offer the advantages of diversification and professional management.</p></li></ul></div><h3 id="core-functions-of-financial-products" tabindex="-1">Core Functions of Financial Products <a class="header-anchor" href="#core-functions-of-financial-products" aria-label="Permalink to &quot;Core Functions of Financial Products&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Core Functions of Financial Products</p><ul><li><p><strong>Capital Formation and Allocation</strong><br> Financial products serve as a channel for efficiently transferring funds from savers (investors) to businesses or governments in need of capital. This facilitates the formation of capital necessary for economic growth.</p></li><li><p><strong>Risk Transfer and Management</strong><br> Financial products, particularly derivatives, enable the transfer of risk to market participants willing and able to bear it, allowing for efficient risk management.</p></li><li><p><strong>Liquidity Provision</strong><br> Financial products provide various maturities and risk-return profiles, allowing investors to secure liquidity that meets their needs.</p></li><li><p><strong>Information Aggregation and Price Discovery</strong><br> The prices of financial products reflect the collective intelligence of market participants, providing an aggregated valuation and expectations regarding underlying assets or future events.</p></li><li><p><strong>Provision of Savings and Investment Instruments</strong><br> Financial products offer a variety of savings and investment instruments for individuals and institutions to accumulate assets and plan for future consumption.</p></li></ul></div><h2 id="_2️⃣-major-types-and-characteristics-of-financial-products" tabindex="-1">2️⃣ Major Types and Characteristics of Financial Products <a class="header-anchor" href="#_2️⃣-major-types-and-characteristics-of-financial-products" aria-label="Permalink to &quot;2️⃣ Major Types and Characteristics of Financial Products&quot;">​</a></h2><h3 id="stocks-stocks-equities" tabindex="-1">Stocks (Stocks/Equities) <a class="header-anchor" href="#stocks-stocks-equities" aria-label="Permalink to &quot;Stocks (Stocks/Equities)&quot;">​</a></h3><p>Stocks are securities that represent ownership in a company and constitute the capital of the issuing company.</p><div class="tip custom-block"><p class="custom-block-title">Key Characteristics of Stocks</p><ul><li><p><strong>Ownership and Voting Rights</strong><br> As partial owners of the company, shareholders can exercise voting rights at shareholder meetings. They can influence corporate decisions in proportion to the number of shares they hold.</p></li><li><p><strong>Dividend Rights</strong><br> If a company decides to distribute a portion of its profits to shareholders, the shareholder has the right to receive dividends in proportion to the number of shares they hold.</p></li><li><p><strong>Capital Gains</strong><br> Shareholders can realize capital gains by selling their stocks when the stock price rises, which is the difference between the purchase price and the selling price.</p></li><li><p><strong>Residual Claim</strong><br> In the event of corporate liquidation, shareholders have a residual claim on the remaining assets after creditors have been repaid.</p></li><li><p><strong>Infinite Maturity</strong><br> Stocks are perpetual securities with no fixed maturity. They continue to exist as long as the company is in operation.</p></li><li><p><strong>Price Volatility</strong><br> Stock prices can fluctuate significantly due to various factors, including company performance, economic conditions, and market sentiment, resulting in relatively high risk.</p></li></ul></div><h3 id="stock-valuation-models" tabindex="-1">Stock Valuation Models <a class="header-anchor" href="#stock-valuation-models" aria-label="Permalink to &quot;Stock Valuation Models&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Stock Valuation Methods</p><ul><li><p><strong>Dividend Discount Model (DDM)</strong><br> This model evaluates stock value based on the present value of all expected future dividends. The most basic form is the Gordon Growth Model:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = D₁ / (r - g)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Where P is the stock price, D₁ is the next period&#39;s dividend, r is the required rate of return, and g is the dividend growth rate.</p></li><li><p><strong>Discounted Cash Flow Method (DCF)</strong><br> This method assesses the value of a company based on the present value of all expected future cash flows and calculates per-share value by dividing it by the number of shares.</p></li><li><p><strong>Relative Valuation Method</strong><br> This approach uses indicators such as P/E (Price-to-Earnings ratio), P/B (Price-to-Book ratio), and EV/EBITDA to evaluate relative value through comparisons with peer companies in the industry.</p></li><li><p><strong>Option Pricing Model</strong><br> This method values a company&#39;s stock by treating it as a call option, which is particularly useful for valuing financially distressed companies or growth companies.</p></li></ul></div><h3 id="bonds" tabindex="-1">Bonds <a class="header-anchor" href="#bonds" aria-label="Permalink to &quot;Bonds&quot;">​</a></h3><p>Bonds are debt securities issued by governments, corporations, and others for the purpose of raising funds, with a set maturity date and interest rate.</p><div class="danger custom-block"><p class="custom-block-title">Key Characteristics of Bonds</p><ul><li><p><strong>Principal and Interest</strong><br> Bondholders receive the principal (face value) at maturity and receive interest (coupons) according to a predetermined schedule.</p></li><li><p><strong>Fixed Maturity</strong><br> Bonds have a maturity date determined at the time of issuance, which can range from several months to several decades.</p></li><li><p><strong>Credit Risk</strong><br> This is the risk associated with the possibility of the issuer defaulting on its debt, with lower credit ratings tending to offer higher interest rates (yields).</p></li><li><p><strong>Interest Rate Risk</strong><br> This is the risk that bond prices will fluctuate due to changes in market interest rates, with longer maturities being more sensitive to interest rate changes.</p></li><li><p><strong>Liquidity Risk</strong><br> Some bonds may not be actively traded, making it difficult to sell them at a fair price when desired.</p></li><li><p><strong>Priority Claim</strong><br> In the event of company liquidation, bondholders can exercise a claim on assets before shareholders.</p></li></ul></div><h3 id="bond-valuation-model" tabindex="-1">Bond Valuation Model <a class="header-anchor" href="#bond-valuation-model" aria-label="Permalink to &quot;Bond Valuation Model&quot;">​</a></h3><p>The value of a bond is evaluated as the sum of the present value of future cash flows (interest and principal):</p><div class="info custom-block"><p class="custom-block-title">Bond Valuation Formula</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P = Σ(C_t / (1+r)^t) + F / (1+r)^T</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here:</p><ul><li>P is the bond price</li><li>C_t is the coupon paid at time t</li><li>F is the principal (face value) paid at maturity</li><li>r is the discount rate (yield)</li><li>T is the time to maturity</li></ul></div><p>The relationship between bond prices and yields is inverse, and this relationship exhibits the following characteristics:</p><div class="tip custom-block"><p class="custom-block-title">The relationship between bond prices and yields</p><ul><li><p><strong>Price-Yield Inverse Relationship</strong><br> When bond prices rise, yields fall, and when prices fall, yields rise.</p></li><li><p><strong>Duration</strong><br> It is an indicator that measures the sensitivity of bond prices to interest rate changes, varying with maturity, coupon rate, and yield.</p></li><li><p><strong>Convexity</strong><br> It is an indicator that measures the rate of change of duration in response to interest rate changes; the greater the convexity, the more the price increases when rates fall, and the less the price decreases when rates rise.</p></li></ul></div><p>Bonds are important financial products for managing interest rate risk, diversifying portfolios, and securing stable cash flows.</p><h3 id="derivatives" tabindex="-1">Derivatives <a class="header-anchor" href="#derivatives" aria-label="Permalink to &quot;Derivatives&quot;">​</a></h3><p>Derivatives are financial contracts whose value is derived from the value of an underlying asset, used for risk management and speculation purposes.</p><div class="warning custom-block"><p class="custom-block-title">Key Characteristics of Derivatives</p><ul><li><p><strong>Dependence on Underlying Assets</strong><br> The value of derivatives is determined by fluctuations in the value of underlying assets such as stocks, bonds, commodities, interest rates, and exchange rates.</p></li><li><p><strong>Leverage Effect</strong><br> Investors can take large trading positions relative to the underlying asset with a small amount of capital, which can lead to high returns or losses.</p></li><li><p><strong>Hedging Tool</strong><br> Derivatives can be used as hedging tools to offset losses in positions exposed to specific risks.</p></li><li><p><strong>Speculative Instrument</strong><br> They are also used as speculative instruments to seek profits based on opinions about future market directions.</p></li><li><p><strong>Contractual Nature</strong><br> Derivatives are fundamentally contracts between parties that establish rights and obligations.</p></li></ul></div><h4 id="main-types-of-derivatives" tabindex="-1">Main Types of Derivatives <a class="header-anchor" href="#main-types-of-derivatives" aria-label="Permalink to &quot;Main Types of Derivatives&quot;">​</a></h4><div class="danger custom-block"><p class="custom-block-title">Main Types of Derivatives</p><ul><li><p><strong>Futures</strong><br> A standardized contract to buy or sell an underlying asset at a predetermined price at a specific future date. It is traded on exchanges and manages credit risk through a daily settlement system.</p></li><li><p><strong>Forwards</strong><br> Similar to futures but are customized contracts traded over-the-counter (OTC), with settlement occurring only at maturity. They offer greater flexibility but come with counterparty risk.</p></li><li><p><strong>Options</strong><br> A contract that grants the right (but not the obligation) to buy or sell an underlying asset at a predetermined price (strike price) at a specific future date or before. There are call options (right to buy) and put options (right to sell), with the option buyer paying a premium to obtain the right.</p></li><li><p><strong>Swaps</strong><br> A contract in which two parties agree to exchange cash flows over a specified period. Common types include interest rate swaps (exchange of fixed and floating rates), currency swaps (exchange of principal and interest in different currencies), and credit default swaps (exchange of credit risk).</p></li><li><p><strong>Credit Derivatives</strong><br> Derivatives based on credit risk, with common examples including credit default swaps (CDS) and collateralized debt obligations (CDO). They allow for the separation and trading of credit risk.</p></li></ul></div><h4 id="valuation-of-derivative-instruments" tabindex="-1">Valuation of Derivative Instruments <a class="header-anchor" href="#valuation-of-derivative-instruments" aria-label="Permalink to &quot;Valuation of Derivative Instruments&quot;">​</a></h4><p>The valuation of derivatives is one of the core areas of financial engineering:</p><div class="info custom-block"><p class="custom-block-title">Valuation Models for Derivatives</p><ul><li><p><strong>Black-Scholes Model</strong><br> This is the most fundamental model for option pricing, particularly widely used for pricing European options. It is based on the following assumptions:</p><ul><li>The underlying asset price follows geometric Brownian motion.</li><li>The risk-free interest rate and volatility are constants.</li><li>No transaction costs or taxes.</li><li>Continuous trading is possible.</li><li>No arbitrage opportunities exist.</li></ul></li><li><p><strong>Binomial Model</strong><br> This model considers only two possibilities for the underlying asset price to either rise or fall within a discrete time framework. It is intuitive and flexible, making it useful for pricing various types of options.</p></li><li><p><strong>Monte Carlo Simulation</strong><br> This method calculates the expected return of derivatives by simulating numerous future paths of the underlying asset price, which is useful for valuing complex derivatives or those based on multiple underlying assets.</p></li><li><p><strong>Finite Difference Methods</strong><br> This numerical method is used to solve partial differential equations and is utilized in option pricing. It is employed to obtain numerical solutions to the Black-Scholes equation.</p></li></ul></div><p>Derivatives are used for various purposes, from risk management to speculative trading, contributing to the efficiency and completeness of financial markets.</p><h2 id="_3️⃣-structured-financial-products" tabindex="-1">3️⃣ Structured Financial Products <a class="header-anchor" href="#_3️⃣-structured-financial-products" aria-label="Permalink to &quot;3️⃣ Structured Financial Products&quot;">​</a></h2><p>Structured Financial Products are complex instruments created by combining or restructuring existing financial products, designed to meet specific investment objectives or risk-return profiles.</p><h3 id="components-and-characteristics-of-structured-products" tabindex="-1">Components and Characteristics of Structured Products <a class="header-anchor" href="#components-and-characteristics-of-structured-products" aria-label="Permalink to &quot;Components and Characteristics of Structured Products&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Components of Structured Products</p><ul><li><strong>Underlying Assets</strong><br> These are the assets that determine the performance of the structured product, including stocks, bonds, commodities, currencies, and indices.</li><li><strong>Derivative Contracts</strong><br> Derivatives such as options and swaps are used to modify the performance of the underlying assets or to create conditional return structures.</li><li><strong>Funding Instruments</strong><br> Stable cash flows are secured through bonds, deposits, etc., which are then utilized for derivative investments.</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Characteristics of Structured Products</p><ul><li><p><strong>Customized Risk-Return Profile</strong><br> The risk and return characteristics can be adjusted to meet the specific needs of investors.</p></li><li><p><strong>Complexity</strong><br> The combination of various financial products can lead to complex structures and pricing mechanisms, making them difficult to understand.</p></li><li><p><strong>Illiquidity</strong><br> Due to the customized features, trading in the secondary market may be limited, resulting in higher liquidity risk.</p></li><li><p><strong>Counterparty Risk</strong><br> The OTC trading structure may expose investors to the credit risk of the counterparty.</p></li><li><p><strong>Regulatory and Tax Efficiency</strong><br> They may offer efficient structures within certain regulatory environments or tax systems.</p></li></ul></div><h3 id="major-types-of-structured-products" tabindex="-1">Major Types of Structured Products <a class="header-anchor" href="#major-types-of-structured-products" aria-label="Permalink to &quot;Major Types of Structured Products&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Major Types of Structured Products</p><ul><li><p><strong>Structured Deposits</strong><br> Products that provide returns linked to the performance of specific indices or assets while guaranteeing the principal. For example, part of the deposit interest may be invested in stock index call options, providing additional returns when the index rises.</p></li><li><p><strong>Asset-Backed Securities (ABS)</strong><br> Securities issued based on underlying assets such as auto loans and credit card receivables, which convey the cash flows from the underlying assets to investors.</p></li><li><p><strong>Mortgage-Backed Securities (MBS)</strong><br> Securities issued based on mortgage loans, where the principal and interest payments from homeowners are transferred to investors.</p></li><li><p><strong>Collateralized Debt Obligations (CDO)</strong><br> Securities issued backed by various debt products, divided into different tranches that offer varying risk-return profiles.</p></li><li><p><strong>Credit-Linked Notes (CLN)</strong><br> Bonds linked to credit events (e.g., default) of specific reference entities or assets, serving as instruments for trading credit risk.</p></li><li><p><strong>Exotic Options</strong><br> Options with more complex conditions or return structures than standard options, including barrier options, Asian options, and digital options.</p></li><li><p><strong>Guaranteed Products</strong><br> Products that provide returns linked to the rise of specific indices or assets while guaranteeing the principal, suitable for conservative investors.</p></li></ul></div><h3 id="valuation-and-risk-management-of-structured-products" tabindex="-1">Valuation and Risk Management of Structured Products <a class="header-anchor" href="#valuation-and-risk-management-of-structured-products" aria-label="Permalink to &quot;Valuation and Risk Management of Structured Products&quot;">​</a></h3><p>Due to the complexity of structured products, valuation and risk management are important financial engineering tasks:</p><div class="info custom-block"><p class="custom-block-title">Valuation Methods for Structured Products</p><ul><li><p><strong>Decomposition Approach</strong><br> This method involves breaking down a structured product into its basic components, evaluating the value of each, and then summing them up.</p></li><li><p><strong>Monte Carlo Simulation</strong><br> This method simulates various paths of the underlying asset price to calculate the expected returns of structured products, making it suitable for complex return structures.</p></li><li><p><strong>Numerical Methods</strong><br> This technique utilizes finite difference methods, tree models, etc., to numerically evaluate the value of structured products.</p></li><li><p><strong>Market Price Comparison</strong><br> This method assesses relative value by referencing the market prices of similar structured products.</p></li></ul></div><div class="tip custom-block"><p class="custom-block-title">Risk Management of Structured Products</p><ul><li><p><strong>Sensitivity Analysis</strong><br> This analyzes the fluctuations in product value based on changes in key variables such as the underlying asset price, volatility, and interest rates, using sensitivity indicators represented by Greek letters (Delta, Gamma, Vega, Theta, Rho).</p></li><li><p><strong>Scenario Analysis</strong><br> This evaluates the performance of the product under various assumed market conditions to assess risk in extreme situations.</p></li><li><p><strong>Stress Testing</strong><br> This tests the performance of structured products by assuming extreme market conditions similar to past financial crises.</p></li><li><p><strong>Dynamic Hedging</strong><br> This continuously adjusts exposure to the underlying asset, interest rates, and volatility to manage the overall portfolio&#39;s risk.</p></li></ul></div><p>Structured products are one of the most active areas of application in financial engineering, driving the development of innovative product designs and sophisticated risk management techniques.</p><h2 id="_4️⃣-investment-funds-and-portfolio-products" tabindex="-1">4️⃣ Investment Funds and Portfolio Products <a class="header-anchor" href="#_4️⃣-investment-funds-and-portfolio-products" aria-label="Permalink to &quot;4️⃣ Investment Funds and Portfolio Products&quot;">​</a></h2><p>Investment funds are products that gather funds from multiple investors and are managed by professional management firms to invest in various assets, providing individual investors with the benefits of professional asset management and diversification.</p><h3 id="types-and-characteristics-of-investment-funds" tabindex="-1">Types and Characteristics of Investment Funds <a class="header-anchor" href="#types-and-characteristics-of-investment-funds" aria-label="Permalink to &quot;Types and Characteristics of Investment Funds&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Fund Types Based on Legal Structure</p><ul><li><p><strong>Mutual Funds</strong><br> These are open-end funds where investors can invest or redeem their shares at any time, with prices determined by the net asset value (NAV). They are a popular retail investment product and are subject to strict regulations.</p></li><li><p><strong>Exchange-Traded Funds (ETFs)</strong><br> Funds designed to track indices that are traded in real-time on exchanges like stocks. They often have lower trading costs and higher tax efficiency compared to mutual funds.</p></li><li><p><strong>Hedge Funds</strong><br> Private investment funds targeted at qualified investors (primarily high-net-worth individuals and institutional investors) with less stringent regulations, allowing for a variety of investment strategies and leverage.</p></li><li><p><strong>Private Equity Funds</strong><br> Funds that invest in private companies, aiming to enhance the corporate value from a long-term investment perspective. They tend to have low liquidity and long investment durations.</p></li><li><p><strong>Venture Capital Funds</strong><br> Funds that invest in early-stage startups, seeking potentially high returns with high risks.</p></li><li><p><strong>Real Estate Investment Trusts (REITs)</strong><br> Products that invest in commercial real estate and distribute rental income and capital gains to investors, providing a liquid means of real estate investment.</p></li></ul></div><div class="warning custom-block"><p class="custom-block-title">Fund Types by Investment Strategy</p><ul><li><p><strong>Active Funds</strong><br> These are funds where fund managers actively select stocks and time the market in order to generate alpha (α) that exceeds market returns.</p></li><li><p><strong>Passive Funds</strong><br> Funds that track a specific index and provide beta (β) close to market returns, characterized by low operating costs.</p></li><li><p><strong>Smart Beta Funds</strong><br> Funds that follow strategic indices based on specific factors (such as value, momentum, quality, etc.) and seek additional returns compared to traditional market capitalization-weighted indices.</p></li><li><p><strong>Absolute Return Funds</strong><br> Funds that aim for positive (+) returns regardless of market conditions, utilizing various investment strategies and risk management techniques.</p></li><li><p><strong>Multi-Asset Funds</strong><br> Funds that invest in a variety of asset classes, such as stocks, bonds, and alternative investments, to maximize diversification effects.</p></li><li><p><strong>Lifecycle/Target-Date Funds</strong><br> Funds that automatically adjust asset allocation over time according to the investor&#39;s target retirement year.</p></li></ul></div><h3 id="measuring-and-evaluating-fund-performance" tabindex="-1">Measuring and Evaluating Fund Performance <a class="header-anchor" href="#measuring-and-evaluating-fund-performance" aria-label="Permalink to &quot;Measuring and Evaluating Fund Performance&quot;">​</a></h3><p>Financial engineering provides various metrics to measure and evaluate fund performance:</p><div class="danger custom-block"><p class="custom-block-title">Fund Performance Measurement Metrics</p><ul><li><p><strong>Sharpe Ratio</strong><br> A metric that measures excess return relative to the risk-free rate per unit of risk (standard deviation), assessing profitability relative to risk.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sharpe Ratio = (R_p - R_f) / σ_p</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, R_p is the portfolio return, R_f is the risk-free return, and σ_p is the portfolio standard deviation.</p></li><li><p><strong>Treynor Ratio</strong><br> It is a measure of excess return relative to the risk-free return, measured per unit of systematic risk (beta).</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Treynor Ratio = (R_p - R_f) / β_p</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, β_p is the beta of the portfolio.</p></li><li><p><strong>Jensen&#39;s Alpha</strong><br> It is an indicator that measures the excess return compared to the expected return according to the Capital Asset Pricing Model (CAPM), evaluating the stock selection ability of the portfolio manager.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>α_p = R_p - [R_f + β_p(R_m - R_f)]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, R_m is the market return.</p></li><li><p><strong>Information Ratio</strong><br> It is a measure that assesses active management capability by measuring excess return (active return) relative to a benchmark per unit of tracking error.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Information Ratio = (R_p - R_b) / TE_p</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, R_b is the benchmark return and TE_p is the tracking error.</p></li><li><p><strong>Sortino Ratio</strong><br> A variation of the Sharpe Ratio that evaluates profitability in relation to downside risk by considering only downside volatility rather than total volatility.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Sortino Ratio = (R_p - R_f) / σ_down</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Here, σ_down refers to the downside standard deviation.</p></li></ul></div><p>These performance metrics help investors compare and evaluate the risk-return characteristics of funds and serve as the basis for asset allocation decisions.</p><h2 id="_5️⃣-alternative-investments" tabindex="-1">5️⃣ Alternative Investments <a class="header-anchor" href="#_5️⃣-alternative-investments" aria-label="Permalink to &quot;5️⃣ Alternative Investments&quot;">​</a></h2><p>Alternative investments refer to investments in assets other than traditional stocks and bonds, providing diversification benefits and differentiated return opportunities.</p><h3 id="key-types-of-alternative-investments" tabindex="-1">Key Types of Alternative Investments <a class="header-anchor" href="#key-types-of-alternative-investments" aria-label="Permalink to &quot;Key Types of Alternative Investments&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Types of Alternative Investment Assets</p><ul><li><p><strong>Real Estate</strong><br> Investments can be made in various forms such as commercial real estate, residential real estate, REITs, and real estate funds, pursuing rental income and capital gains.</p></li><li><p><strong>Private Equity &amp; Venture Capital</strong><br> Investing in privately held companies to seek high returns through the enhancement of corporate value. Unlike publicly listed stocks, there are opportunities for value creation through liquidity premiums and operational improvements.</p></li><li><p><strong>Hedge Funds</strong><br> Utilizing various investment strategies (long/short, macro, event-driven, etc.) to pursue absolute returns regardless of market conditions.</p></li><li><p><strong>Commodities</strong><br> Investing directly in physical assets like gold, crude oil, and agricultural products or indirectly through futures and ETFs. This offers an inflation hedging effect.</p></li><li><p><strong>Infrastructure</strong><br> Investing in social infrastructure such as roads, ports, airports, and energy facilities to seek stable long-term returns. The revenue stability is characterized by its connection to government policies.</p></li><li><p><strong>Art &amp; Collectibles</strong><br> Investing in artworks, wine, luxury watches, classic cars, etc., to seek returns through value appreciation. Pricing is characterized by appraisal value and scarcity.</p></li><li><p><strong>Cryptocurrencies</strong><br> Investing in digital assets like Bitcoin and Ethereum, characterized by high volatility and low correlation with existing financial systems.</p></li><li><p><strong>Insurance-Linked Securities</strong><br> Products that securitize risks associated with natural disasters, where returns are determined based on the occurrence of disasters, resulting in very low correlation with financial markets.</p></li></ul></div><h3 id="characteristics-of-alternative-investments-and-portfolio-effects" tabindex="-1">Characteristics of Alternative Investments and Portfolio Effects <a class="header-anchor" href="#characteristics-of-alternative-investments-and-portfolio-effects" aria-label="Permalink to &quot;Characteristics of Alternative Investments and Portfolio Effects&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Key Characteristics of Alternative Investments</p><ul><li><p><strong>Low Liquidity</strong><br> Alternative investments generally have low liquidity, meaning it takes time to recover the invested capital, and there is a liquidity premium as compensation for this.</p></li><li><p><strong>Inefficient Markets</strong><br> Due to information asymmetry and barriers to expertise, market inefficiencies may lead to more opportunities for alpha generation.</p></li><li><p><strong>Complex Structures</strong><br> Investment structures, fee systems, and legal requirements are complex and require specialized knowledge.</p></li><li><p><strong>Limited Access</strong><br> High minimum investment amounts and accredited investor requirements restrict access.</p></li><li><p><strong>Challenges in Performance Measurement</strong><br> Without publicly available market prices, performance measurement can be difficult, and there are specific performance patterns such as the J-curve effect (a temporary decline in performance after initial investment followed by an increase).</p></li></ul></div><div class="danger custom-block"><p class="custom-block-title">Effects of Alternative Investments in Portfolios</p><ul><li><p><strong>Diversification Benefits</strong><br> The diversification effect from low correlation with traditional assets can reduce the overall risk of the portfolio.</p></li><li><p><strong>Return Enhancement</strong><br> Due to liquidity premiums and complexity premiums, alternative investments can offer higher expected returns.</p></li><li><p><strong>Inflation Hedging</strong><br> Real estate and commodities have a positive correlation with inflation, making them useful as inflation hedges.</p></li><li><p><strong>Market-Neutral Returns</strong><br> Strategies that pursue absolute returns regardless of market direction provide defensive benefits during market downturns.</p></li><li><p><strong>Asset-Liability Matching</strong><br> As long-term investment assets, alternative investments are useful for matching with long-term liabilities such as pensions.</p></li></ul></div><p>Alternative investments are becoming more sophisticated with the advancement of financial engineering, and access is gradually expanding for not only institutional investors but also individual investors.</p><h2 id="_6️⃣-financial-product-risk-management-and-regulation" tabindex="-1">6️⃣ Financial Product Risk Management and Regulation <a class="header-anchor" href="#_6️⃣-financial-product-risk-management-and-regulation" aria-label="Permalink to &quot;6️⃣ Financial Product Risk Management and Regulation&quot;">​</a></h2><p>Financial products carry various risks, and effectively managing and regulating them is crucial for the stability of the financial system and the protection of investors.</p><h3 id="main-types-of-risks-in-financial-products" tabindex="-1">Main Types of Risks in Financial Products <a class="header-anchor" href="#main-types-of-risks-in-financial-products" aria-label="Permalink to &quot;Main Types of Risks in Financial Products&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Main Risks of Financial Products</p><ul><li><p><strong>Market Risk</strong><br> The risk of loss due to fluctuations in market prices (such as stock prices, interest rates, exchange rates, commodity prices), which is the most fundamental risk associated with financial products.</p></li><li><p><strong>Credit Risk</strong><br> The risk that a counterparty fails to fulfill its contractual obligations, which is an important consideration in bonds, derivatives, and other financial contracts.</p></li><li><p><strong>Liquidity Risk</strong><br> The risk of being unable to sell an asset at a reasonable price at the desired time, which can intensify during market stress situations.</p></li><li><p><strong>Operational Risk</strong><br> The risk of loss resulting from internal processes, personnel, system failures, or external events.</p></li><li><p><strong>Legal &amp; Regulatory Risk</strong><br> The risk arising from changes in laws or regulations, which is particularly significant in cross-border transactions.</p></li><li><p><strong>Model Risk</strong><br> The risk arising from errors or inappropriate applications of financial models, which is especially important in complex financial products.</p></li><li><p><strong>Systemic Risk</strong><br> A broad risk that affects the entire financial system, which is becoming increasingly important in modern financial markets characterized by high interconnectedness.</p></li></ul></div><h3 id="risk-measurement-and-management-techniques-for-financial-products" tabindex="-1">Risk Measurement and Management Techniques for Financial Products <a class="header-anchor" href="#risk-measurement-and-management-techniques-for-financial-products" aria-label="Permalink to &quot;Risk Measurement and Management Techniques for Financial Products&quot;">​</a></h3><p>Financial engineering offers various techniques for quantitatively measuring and managing risk:</p><div class="warning custom-block"><p class="custom-block-title">Risk Measurement and Management Techniques</p><ul><li><p><strong>Value at Risk (VaR)</strong><br> An indicator that estimates the maximum loss that may occur over a given period at a specific confidence level, widely used as a standard for risk measurement.<br> Calculation Methods:</p><ul><li>Historical Simulation</li><li>Variance-Covariance Method</li><li>Monte Carlo Simulation</li></ul></li><li><p><strong>Conditional Value at Risk (CVaR/Expected Shortfall)</strong><br> The expected value of losses exceeding VaR, which better captures tail risk.</p></li><li><p><strong>Stress Testing</strong><br> A method to test portfolio performance under extreme market conditions, which has gained importance since the 2008 financial crisis.</p></li><li><p><strong>Scenario Analysis</strong><br> A method for assessing risk by setting up scenarios based on various market conditions.</p></li><li><p><strong>Risk Decomposition</strong><br> A method that analyzes total risk by breaking it down into various components (market, credit, liquidity, etc.) or by asset.</p></li><li><p><strong>Sensitivity Analysis</strong><br> A method for analyzing changes in portfolio value resulting from shifts in key risk factors such as interest rates and volatility.</p></li><li><p><strong>Hedging Strategies</strong><br> Strategies that utilize derivatives to offset specific risk exposure, including delta hedging and gamma hedging.</p></li></ul></div><h3 id="regulation-of-financial-products-and-investor-protection" tabindex="-1">Regulation of Financial Products and Investor Protection <a class="header-anchor" href="#regulation-of-financial-products-and-investor-protection" aria-label="Permalink to &quot;Regulation of Financial Products and Investor Protection&quot;">​</a></h3><p>Regulation of financial products aims to protect investors, maintain market stability, and manage systemic risk:</p><div class="danger custom-block"><p class="custom-block-title">Financial Product Regulatory Framework</p><ul><li><p><strong>Disclosure Requirements</strong><br> Requires sufficient disclosure of information regarding the characteristics, risks, fees, etc., of financial products to enable investors to make informed decisions.</p></li><li><p><strong>Suitability Test</strong><br> Regulation that ensures only suitable financial products are recommended based on the investor&#39;s knowledge, experience, financial situation, and investment goals.</p></li><li><p><strong>Exchange Trading Mandate</strong><br> A regulation that mandates the on-exchange trading of certain derivatives to enhance transparency and stability.</p></li><li><p><strong>Central Clearing Requirement</strong><br> Mandates the use of central clearinghouses (CCPs) for OTC derivatives to manage counterparty risk.</p></li><li><p><strong>Capital Requirements</strong><br> Requires financial institutions to maintain sufficient capital to enhance their ability to absorb risks.</p></li><li><p><strong>Product Intervention Powers</strong><br> Authority for regulatory bodies to restrict or prohibit the sale of financial products that may be harmful to investors.</p></li><li><p><strong>Consumer Protection Laws</strong><br> Regulations aimed at protecting the rights of financial consumers and preventing unfair selling practices.</p></li></ul></div><p>Risk management and regulation of financial products are important areas of application in financial engineering, becoming more stringent and sophisticated following the 2008 global financial crisis.</p><h2 id="_7️⃣-innovation-in-financial-products-and-future-trends" tabindex="-1">7️⃣ Innovation in Financial Products and Future Trends <a class="header-anchor" href="#_7️⃣-innovation-in-financial-products-and-future-trends" aria-label="Permalink to &quot;7️⃣ Innovation in Financial Products and Future Trends&quot;">​</a></h2><p>The financial market is continuously evolving due to technological advancements, changes in the economic environment, and regulatory shifts, leading to the emergence of new financial products and services.</p><h3 id="key-drivers-of-financial-product-innovation" tabindex="-1">Key Drivers of Financial Product Innovation <a class="header-anchor" href="#key-drivers-of-financial-product-innovation" aria-label="Permalink to &quot;Key Drivers of Financial Product Innovation&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Drivers of Financial Product Innovation</p><ul><li><p><strong>Technological Advancements</strong><br> The emergence of new technologies such as big data, artificial intelligence, and blockchain is innovating the design, pricing, and transaction methods of financial products.</p></li><li><p><strong>Changing Investor Needs</strong><br> As investor demands shift towards ESG investing, personalized investment solutions, and a preference for passive investment, new products are being developed.</p></li><li><p><strong>Advancements in Risk Management</strong><br> The development of more sophisticated risk management techniques is giving rise to financial products that address new types of risks.</p></li><li><p><strong>Changes in Regulatory Environment</strong><br> Product innovations are being made in response to changes in financial regulations or to enhance regulatory efficiency.</p></li><li><p><strong>Intensifying Market Competition</strong><br> Increased competition between traditional financial institutions and fintech companies is accelerating the development of differentiated financial products.</p></li></ul></div><h3 id="recent-innovations-in-financial-products" tabindex="-1">Recent Innovations in Financial Products <a class="header-anchor" href="#recent-innovations-in-financial-products" aria-label="Permalink to &quot;Recent Innovations in Financial Products&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Innovations in Financial Products</p><ul><li><p><strong>Digital Assets &amp; Tokenization</strong><br> Innovations are underway that utilize blockchain technology to tokenize physical assets (such as real estate, artworks, etc.), enabling fractional ownership and trading.</p></li><li><p><strong>Decentralized Finance (DeFi)</strong><br> A decentralized financial ecosystem based on blockchain that offers a variety of financial services, including lending, trading, and derivatives, without intermediaries.</p></li><li><p><strong>ESG Financial Products</strong><br> Investment products that consider environmental, social, and governance factors, including sustainable bonds, impact investment funds, and green mortgages.</p></li><li><p><strong>Automated Investment Advisors</strong><br> Algorithm-based robo-advisors provide personalized asset allocation and investment services at low costs.</p></li><li><p><strong>Factor-Based Investment Products</strong><br> Products like ETFs that provide exposure to specific investment factors such as value, momentum, and quality are expanding.</p></li><li><p><strong>Insurance-Linked Securities</strong><br> Products that securitize risks from natural disasters, pandemics, and other events, making them available for investment.</p></li><li><p><strong>Digital Platform-Based Investment Products</strong><br> Services are increasing that allow small investments in stocks or thematic investments through mobile apps.</p></li></ul></div><h3 id="future-trends-in-financial-products" tabindex="-1">Future Trends in Financial Products <a class="header-anchor" href="#future-trends-in-financial-products" aria-label="Permalink to &quot;Future Trends in Financial Products&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Future Trends in Financial Products</p><ul><li><p><strong>Hyper-personalization</strong><br> The trend of providing completely tailored financial products by analyzing individuals&#39; financial situations, preferences, and behavior patterns using big data and AI will strengthen.</p></li><li><p><strong>Embedded Finance</strong><br> Financial services will be integrated into non-financial platforms or apps, blurring the lines between finance and everyday life.</p></li><li><p><strong>Mainstreaming of Sustainable Finance</strong><br> The tendency to integrate ESG factors into the design and evaluation of all financial products will be reinforced.</p></li><li><p><strong>Decentralization &amp; Democratization</strong><br> Through blockchain and P2P technology, the decentralization of financial services will progress, and access to financial products that were previously centered around institutional investors will expand to individual investors.</p></li><li><p><strong>Integration with RegTech</strong><br> Financial products will evolve to include regulatory compliance mechanisms, which will enhance regulatory efficiency.</p></li><li><p><strong>Quantum Finance</strong><br> As quantum computing technology advances, complex financial calculations that are currently impossible may become feasible, facilitating the development of new financial products.</p></li><li><p><strong>Autonomous Financial Agents</strong><br> With the advancement of AI, there is a possibility that agents will emerge that autonomously make financial decisions on behalf of investors.</p></li></ul></div><p>Financial engineering will continue to be a key field driving these innovations and trends, providing scientific methodologies for the design, pricing, and risk management of new financial products. As the complexity and interconnectedness of financial markets increase, the importance of financial engineering is expected to grow even further.</p><h2 id="_8️⃣-conclusion-the-importance-of-understanding-financial-products" tabindex="-1">8️⃣ Conclusion: The Importance of Understanding Financial Products <a class="header-anchor" href="#_8️⃣-conclusion-the-importance-of-understanding-financial-products" aria-label="Permalink to &quot;8️⃣ Conclusion: The Importance of Understanding Financial Products&quot;">​</a></h2><p><strong>Financial products are fundamental components of capital markets, playing key roles in capital formation, risk management, and asset allocation within the financial system. Understanding the characteristics, valuation methods, and risk factors of various financial products is essential for learning and applying financial engineering.</strong></p><p>A deep understanding of financial products is important for the following reasons:</p><div class="tip custom-block"><p class="custom-block-title">Importance of Understanding Financial Products</p><ul><li><p><strong>Contextualizing Financial Engineering Models</strong><br> Financial engineering models must reflect the characteristics and constraints of specific financial products, so understanding the products is a prerequisite.</p></li><li><p><strong>Effective Risk Management</strong><br> By understanding the risk characteristics of each financial product, effective risk management strategies can be established.</p></li><li><p><strong>Innovative Product Design</strong><br> By understanding the strengths and weaknesses of existing financial products, innovative products that better meet investor needs can be designed.</p></li><li><p><strong>Improved Investment Decision-Making</strong><br> By understanding the structure and performance drivers of financial products, more informed investment decisions can be made.</p></li><li><p><strong>Considering Regulatory and Ethical Aspects</strong><br> By understanding the social impact and potential risks of financial products, responsible financial innovation can be pursued.</p></li></ul></div><p><strong>In the upcoming series on the fundamentals of financial engineering, core topics such as interest rates, discount rates, option pricing theory, portfolio theory, and risk management will be explored in greater depth based on this foundational understanding of financial products. These theories and methodologies will ultimately contribute to fostering more efficient and equitable financial markets and better investment decisions.</strong></p><h2 id="_9️⃣-references-and-recommended-materials" tabindex="-1">9️⃣ References and Recommended Materials <a class="header-anchor" href="#_9️⃣-references-and-recommended-materials" aria-label="Permalink to &quot;9️⃣ References and Recommended Materials&quot;">​</a></h2><p>For a deeper understanding of financial products, the following materials may be helpful:</p><div class="tip custom-block"><p class="custom-block-title"><strong>Recommended Books</strong></p><ul><li>&quot;Investment Theory&quot; (Author: Won Jae-hwan, Publisher: Park Young-sa)</li><li>&quot;Modern Securities Investment Analysis&quot; (Authors: Park Jeong-sik, Park Jong-won, Cho Jae-ho, Publisher: Dasan Publishing)</li><li>&quot;Understanding Derivatives&quot; (Author: Ryu Geun-sik, Publisher: Hankyungsa)</li><li>&quot;Options, Futures, and Other Derivatives&quot; (Author: John C. Hull, Publisher: Pearson)</li><li>&quot;Fixed Income Securities: Tools for Today&#39;s Markets&quot; (Authors: Bruce Tuckman, Angel Serrat, Publisher: Wiley)</li><li>&quot;Financial Markets and Institutions&quot; (Authors: Frederic S. Mishkin, Stanley G. Eakins, Publisher: Pearson)</li><li>&quot;Structured Products: Alternative Investments for the Retail Market&quot; (Authors: Brian P. Lancaster, Glenn M. Schultz, Publisher: Bloomberg Press)</li></ul></div><div class="warning custom-block"><p class="custom-block-title"><strong>Online resources</strong></p><ul><li>Korea Financial Investment Association Education Center: <a href="https://www.kifin.or.kr/" target="_blank" rel="noreferrer">https://www.kifin.or.kr/</a></li><li>Financial Supervisory Service Financial Education Center: <a href="https://www.fss.or.kr/edu/" target="_blank" rel="noreferrer">https://www.fss.or.kr/edu/</a></li><li>Investopedia (Information on financial products): <a href="https://www.investopedia.com/" target="_blank" rel="noreferrer">https://www.investopedia.com/</a></li><li>Khan Academy - Finance and Capital Markets: <a href="https://www.khanacademy.org/economics-finance-domain/core-finance" target="_blank" rel="noreferrer">https://www.khanacademy.org/economics-finance-domain/core-finance</a></li><li>Yale University - Financial Markets Course: <a href="https://www.coursera.org/learn/financial-markets-global" target="_blank" rel="noreferrer">https://www.coursera.org/learn/financial-markets-global</a></li></ul></div><div class="danger custom-block"><p class="custom-block-title"><strong>Major Financial Information Sites</strong></p><ul><li>Korea Exchange: <a href="https://www.krx.co.kr/" target="_blank" rel="noreferrer">https://www.krx.co.kr/</a></li><li>Korea Financial Investment Association: <a href="https://www.kofia.or.kr/" target="_blank" rel="noreferrer">https://www.kofia.or.kr/</a></li><li>Bloomberg: <a href="https://www.bloomberg.com/" target="_blank" rel="noreferrer">https://www.bloomberg.com/</a></li><li>Financial Times: <a href="https://www.ft.com/" target="_blank" rel="noreferrer">https://www.ft.com/</a></li><li>Morningstar (Fund Information): <a href="https://www.morningstar.com/" target="_blank" rel="noreferrer">https://www.morningstar.com/</a></li><li>ETF.com (ETF Information): <a href="https://www.etf.com/" target="_blank" rel="noreferrer">https://www.etf.com/</a></li></ul></div><div class="info custom-block"><p class="custom-block-title"><strong>Disclaimer</strong></p><ul><li>The content of this blog is written for educational and informational purposes and should not be considered an investment recommendation or a substitute for financial advice. For actual financial decisions, please seek the advice of a professional.</li></ul></div>',99)]))}const g=i(s,[["render",r]]);export{h as __pageData,g as default};
